from pathlib import Path
from html import escape
import json

P=Path(__file__).parent
pages={
'index.html':('Home','Water damage restoration website demo','A fictional Pittsburgh-area restoration website with safe assessment intake and no emergency-response claim.'),
'services.html':('Services','Water damage services','Sample mitigation, drying, moisture mapping and repair coordination pathways for a restoration company.'),
'process.html':('Our Process','An understandable restoration process','A clear assessment, scope, monitoring and handoff workflow with no claims about an actual provider.'),
'commercial.html':('Commercial','Commercial water damage planning','Business property considerations, stakeholder communication and example proposal intake.'),
'service-areas.html':('Service Areas','Pittsburgh-area restoration service demo','Editable location and service-area framework for a verified restoration company.'),
'request-assessment.html':('Request Assessment','Water damage assessment preview','Local-only intake demo. No message is sent and no emergency team is dispatched.'),
}
nav=[('index.html','Home'),('services.html','Services'),('process.html','Process'),('commercial.html','Commercial'),('service-areas.html','Service areas'),('request-assessment.html','Request assessment')]
def a(path,text,cls=''):return f'<a href="/{path}" class="{cls}">{text}</a>'
def page(path,body):
 title,_,desc=pages[path]
 links=''.join(a(x,y,'active' if x==path else '') for x,y in nav)
 schema=json.dumps({'@context':'https://schema.org','@type':'WebPage','name':title+' | Current & Clear fictional demo','description':desc,'isPartOf':{'@type':'WebSite','name':'Current & Clear — demo'}})
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Current &amp; Clear — Restoration Demo</title><meta name="description" content="{escape(desc,quote=True)}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#11252d"><meta property="og:title" content="{title} | Current &amp; Clear"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:image" content="https://fireworks-water-restoration.vercel.app/assets/restoration-hero.webp"><meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="https://fireworks-water-restoration.vercel.app/{'' if path=='index.html' else path}"><link rel="stylesheet" href="/styles.css"><script defer src="/script.js"></script><script type="application/ld+json">{schema}</script></head><body><div class="demo">FIREWORKS FICTIONAL DEMO · NO EMERGENCY SERVICE OR LIVE INQUIRY IS PROVIDED</div><a class="skip" href="#main">Skip to content</a><header class="header wrap"><a class="brand" href="/"><span class="brand-mark">C<span>+</span>C</span><span>CURRENT <i>&amp;</i> CLEAR<small>RESTORATION WEBSITE DEMO</small></span></a><button class="menu" type="button" aria-controls="nav" aria-expanded="false">Menu <span aria-hidden="true">☰</span></button><nav id="nav" aria-label="Main navigation">{links}</nav></header><main id="main">{body}</main><footer class="footer"><div class="wrap footer-grid"><div><strong>CURRENT &amp; CLEAR</strong><p>Fictional restoration website concept. Generated imagery and sample market content are illustrative; no company or emergency service is represented.</p></div><div><b>Explore</b>{a('services.html','Services')}{a('process.html','Process')}{a('request-assessment.html','Assessment preview')}</div><div><b>Client launch inputs</b><p>Verify address, hours, phone, service area, response availability, qualifications, insurance policies and approved intake provider.</p></div></div><div class="wrap footline">© 2026 Current &amp; Clear demo <span>Nothing submitted here is transmitted, stored or dispatched.</span></div></footer></body></html>'''
def intro(kicker,title,copy):return f'<section class="intro wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p>{copy}</p></section>'
def call(title,copy='Preview the information a real business could request. This demo does not connect to a team.'):
 return f'<section class="call"><div class="wrap call-grid"><div><p class="eyebrow">A CLEAR NEXT STEP</p><h2>{title}</h2><p>{copy}</p></div>{a("request-assessment.html","Preview an assessment request ↗","button pale")}</div></section>'

home='''<section class="hero"><img src="/assets/restoration-hero.webp" width="2072" height="759" alt="Generated illustration of a technician checking moisture near a drying fan in a water-affected room" fetchpriority="high"><div class="shade"></div><div class="wrap hero-content"><p class="eyebrow">WATER DAMAGE RESTORATION · PITTSBURGH SAMPLE MARKET</p><h1>When water changes everything,<br><em>start with clarity.</em></h1><p>A measured path from what happened to what comes next. This is a fictional service website preview, with no monitored emergency response.</p><div class="actions"><a class="button" href="/request-assessment.html">Preview an assessment ↗</a><a class="button outline" href="/services.html">Explore services</a></div></div><span class="photo-note">Generated illustrative image · not a real job</span></section><section class="strip"><div class="wrap strip-grid"><span>ASSESS THE DAMAGE</span><span>DEFINE THE SCOPE</span><span>TRACK THE DRYING</span><span>PLAN THE HANDOFF</span></div></section>'''
home+='''<section class="section wrap"><div class="section-head"><div><p class="eyebrow">START WITH THE RIGHT QUESTIONS</p><h2>A clear route through<br>an uncertain moment.</h2></div><p>Useful restoration websites help property owners identify the type of issue, understand a real company’s process, and reach the right team. Actual response times and availability must be verified.</p></div><div class="cards"><a href="/services.html#extraction" class="card"><span>01 / WATER MITIGATION</span><h3>Understand the affected area.</h3><p>Explain extraction and containment as services offered only when confirmed by a client.</p><strong>Explore mitigation ↗</strong></a><a href="/services.html#drying" class="card"><span>02 / STRUCTURAL DRYING</span><h3>Measure. Monitor. Document.</h3><p>Show how equipment and monitoring may fit a properly scoped project.</p><strong>Explore drying ↗</strong></a><a href="/commercial.html" class="card"><span>03 / COMMERCIAL PROPERTY</span><h3>Plan around the business.</h3><p>Route facility managers to an intake designed for property and operational context.</p><strong>Explore commercial ↗</strong></a></div></section><section class="feature"><div class="wrap feature-grid"><div><p class="eyebrow">THE PROCESS MATTERS</p><h2>From discovery<br>to a documented plan.</h2><p>Separate an initial conversation from actual assessment, approval, monitoring and repair coordination. Let the real business state its policies and qualifications.</p><a class="text-link" href="/process.html">View the sample process ↗</a></div><div class="feature-photo"><img src="/assets/restoration-hero.webp" alt="Illustrative drying fan and moisture check" width="2072" height="759" loading="lazy"></div></div></section><section class="section wrap"><div class="section-head"><div><p class="eyebrow">HOMEOWNERS &amp; PROPERTY TEAMS</p><h2>Useful information,<br>without the pressure.</h2></div><p>No made-up response guarantees, certifications or insurance outcomes. Each statement is a placeholder for facts that a real client can verify.</p></div><div class="three"><div><b>Residential</b><p>For homes, identify rooms, source, discovery time and immediate property needs.</p></div><div><b>Commercial</b><p>For facilities, add access constraints, affected operations and the right contact department.</p></div><div><b>Insurance process</b><p>Explain documentation and communication; never imply that claims or coverage are guaranteed.</p></div></div></section>'''+call('Tell the story of the damage.')

services=intro('SAMPLE SERVICE PATHWAYS','The work starts with an assessment.','A real restoration company must confirm which services it performs, its qualifications, pricing, coverage and availability. These sections model clear service pages.')+'''<section class="wrap service-list"><article id="extraction"><span>01 / MITIGATION</span><div><h2>Water removal &amp; containment</h2><p>Describe the source and affected materials, then let a qualified real provider determine extraction, containment and protection steps. The demo makes no emergency claim.</p><a href="/request-assessment.html?service=Water%20mitigation">Preview a mitigation inquiry ↗</a></div></article><article id="drying"><span>02 / DRYING</span><div><h2>Structural drying</h2><p>Describe air movement, dehumidification and documented moisture checks without promising timing or a particular outcome.</p><a href="/request-assessment.html?service=Structural%20drying">Preview a drying inquiry ↗</a></div></article><article id="mapping"><span>03 / DOCUMENTATION</span><div><h2>Moisture mapping</h2><p>Show how a client may record affected spaces and progress. Any certifications or measuring methods must be supplied and verified.</p><a href="/request-assessment.html?service=Moisture%20assessment">Preview an assessment ↗</a></div></article><article id="repairs"><span>04 / HANDOFF</span><div><h2>Repair coordination</h2><p>Explain whether the business handles reconstruction directly or coordinates a separate approved contractor. Insurance decisions belong to the insurer and customer.</p><a href="/request-assessment.html?service=Repair%20coordination">Preview repair coordination ↗</a></div></article></section>'''+call('Start with what happened.')

process=intro('A TRANSPARENT EXAMPLE','Understand every stage.','A practical website can show what to expect without claiming an actual response window, drying duration, insurance approval or guaranteed result.')+'''<section class="wrap timeline"><article><span>01</span><div><h2>Describe the situation.</h2><p>Share the general damage category, location and timing. A real company provides verified contact and urgency instructions.</p></div></article><article><span>02</span><div><h2>Assess the property.</h2><p>A qualified team evaluates the source, affected materials, safety conditions, scope and equipment needs before work begins.</p></div></article><article><span>03</span><div><h2>Approve the scope.</h2><p>Present real pricing, access needs, terms and any insurance-documentation support for the customer to review.</p></div></article><article><span>04</span><div><h2>Monitor and hand off.</h2><p>Document progress and explain any next step for repairs. The actual business defines measurements, reporting and closeout.</p></div></article></section><section class="section wrap"><p class="eyebrow">INSURANCE IS CLIENT-SPECIFIC</p><h2>Documentation without promises.</h2><p class="measure">Coverage depends on the policy, cause and insurer. A real business should explain what it documents and whether it communicates with the adjuster; this demo guarantees neither coverage nor reimbursement.</p></section>'''+call('Share a general assessment request.')

commercial=intro('COMMERCIAL PROPERTY PATHWAY','Protect the plan, not just the property.','An adaptable page for facility teams and property managers. Service capacity, business-continuity support, qualifications and available equipment require client confirmation.')+'''<section class="wrap cards commercial-cards"><div class="card"><span>01 / SITE CONTEXT</span><h3>What is affected?</h3><p>Identify property type, spaces, access, utilities and the contact responsible for approvals.</p></div><div class="card"><span>02 / OPERATIONS</span><h3>What must continue?</h3><p>Frame operational constraints and tenant communication without guaranteeing uninterrupted use.</p></div><div class="card"><span>03 / PROCUREMENT</span><h3>Who approves the scope?</h3><p>Allow a real provider to define documentation, vendor requirements and proposal routing.</p></div></section><section class="section wrap"><div class="section-head"><div><p class="eyebrow">ADAPTABLE INTAKE</p><h2>One form, useful routing.</h2></div><p>The same demo form collects property type and affected area without documents, insurance details or sensitive information. Secure uploads and department routing require a client-approved provider.</p></div></section>'''+call('Start a commercial assessment preview.')

areas=intro('SAMPLE PITTSBURGH-AREA STRUCTURE','Local details that are actually useful.','Replace all region text with a client-verified address, contact, hours and coverage. Avoid duplicate city-name pages or a promise of rapid response.')+'''<section class="wrap area-grid"><div><h2>Pittsburgh &amp; the South Hills</h2><p>This fictional example references Pittsburgh, Mt. Lebanon, Dormont and nearby communities to demonstrate localized site structure. A real provider must define its service area and whether residential or commercial requests are accepted there.</p><p>Use one helpful service-area page with actual coverage limits, office location and driving context when relevant.</p></div><aside><b>VERIFY BEFORE LAUNCH</b><dl><dt>Public contact</dt><dd>Client phone and email</dd><dt>Location</dt><dd>Client address or service-area model</dd><dt>Hours</dt><dd>Actual business hours</dd><dt>Urgent availability</dt><dd>Only if genuinely offered and monitored</dd></dl></aside></section>'''+call('Describe the property and issue.')

request=intro('LOCAL-ONLY ASSESSMENT PREVIEW','Tell us what happened.','This demo validates a general inquiry in your browser. It never transmits or stores information, dispatches a team, checks availability or opens an insurance claim.')+'''<section class="wrap form-layout"><div><h2>Start with essentials.</h2><p>A real site should pair its verified phone and availability with an intake destination. This template has neither.</p><div class="notice"><b>Urgent situations</b><p>This page is not monitored. Contact an appropriate local provider directly using verified contact details; seek emergency services when there is immediate danger.</p></div><p>Do not include private insurance numbers, account details or health information.</p></div><form id="inquiry" class="form"><div class="fields"><label>Name <input name="name" autocomplete="name" required maxlength="100"></label><label>Email <input type="email" name="email" autocomplete="email" required></label><label>Phone <input name="phone" type="tel" autocomplete="tel" pattern="[0-9+() .-]{7,20}" required></label><label>Property ZIP <input name="zip" inputmode="numeric" pattern="[0-9]{5}" required></label><label>Property type <select name="property" required><option value="">Choose type</option><option>Home</option><option>Multi-unit residential</option><option>Commercial</option><option>Other</option></select></label><label>Concern <select name="service" required><option value="">Choose concern</option><option>Water mitigation</option><option>Structural drying</option><option>Moisture assessment</option><option>Repair coordination</option><option>Not sure</option></select></label><label>When discovered <select name="timing" required><option value="">Choose timing</option><option>Today</option><option>Within the last week</option><option>Earlier</option><option>Not sure</option></select></label><label>Affected area <input name="area" required placeholder="Example: first-floor kitchen" maxlength="120"></label></div><label>General description <textarea name="notes" rows="5" maxlength="1000" required placeholder="Briefly describe the issue without sensitive details"></textarea></label><label class="check"><input type="checkbox" required name="ack"> I understand this is a fictional demo, not an emergency contact; nothing is sent, stored or scheduled.</label><button class="button" type="submit">Preview locally ↗</button><div id="result" role="status" aria-live="polite" tabindex="-1"></div></form></section>'''

for path,body in [('index.html',home),('services.html',services),('process.html',process),('commercial.html',commercial),('service-areas.html',areas),('request-assessment.html',request)]:
 (P/path).write_text(page(path,body),encoding='utf-8')
print('Built',len(pages),'water restoration pages')
